import React, { useEffect, useState } from "react";
import WholesaleQuantityDiscountsTable from "./WholesaleQuantityDiscountsTable";
import useApi from "../../../../hooks/useApi";
import { useNavigate } from "react-router-dom";
import { getLoggedInUser } from "../../../../helpers/authUtils";
import PriceDiscountsFormModal from "./WholesaleQuantityDiscountsFormModal";
import wholesalersApi from "../../../../api/wholesalers/wholesalersApi";

const columns = [
  { name: "Banner", uid: "banner" },
  { name: "Title", uid: "title" },
  { name: "Limit Quantity", uid: "limit_quantity_str" },
  { name: "Awarded Quantity", uid: "awarded_quantity_str" },
  { name: "Start Date", uid: "start" },
  { name: "End Date", uid: "end" },
  { name: "Actions", uid: "actions" },
];

function WholesaleQuantityDiscountsList() {
  const [openQuantityDiscountFormModal, setopenQuantityDiscountsFormModal] =
    useState(false);
  const navigate = useNavigate();
  const [quantityDiscount, setQuantityDiscount] = useState();
  const [quantityDiscounts, setQuantityDiscounts] = useState([]);
  const [data, setdata] = useState([]);
  const [updated, setUpdated] = useState(false);
  const [modalTitle, setmodalTitle] = useState("");
  const discountsActionsApi = useApi(wholesalersApi.wholesaleReceiptsAction);

  const [user, setUser] = useState();

  useEffect(() => {
    setUser(getLoggedInUser());
  }, []);

  const getQuantityDiscounts = async (user) => {
    setQuantityDiscounts([]);
    await discountsActionsApi.request({
      action: "WholesalerQuantityDiscounts",
    });
  };

  useEffect(() => {
    getQuantityDiscounts(user);
  }, [user]);

  useEffect(() => {
    getQuantityDiscounts(user);
  }, [openQuantityDiscountFormModal]);

  const handleEditAction = (item) => {
    setopenQuantityDiscountsFormModal(true);

    // setUpdated(false)

    setQuantityDiscount(item);
    setmodalTitle(`${item.title}`);
  };

  const handleAddAction = () => {
    setopenQuantityDiscountsFormModal(true);

    setUpdated(false);

    setmodalTitle("Add new quantity discount");
    setQuantityDiscount(null);
  };
  const handleDetailsAction = (item) => {
    navigate(`/payments/discounts/quantity/details/${item.id}`, {
      state: {
        item: item,
      },
    });
  };
  const handleDeleteAction = (item) => {
    navigate(`/payments/discounts/quantity/delete/${item.id}`);
  };

  useEffect(() => {
    if (discountsActionsApi.data && discountsActionsApi.data.length) {
      setQuantityDiscounts(discountsActionsApi.data);
    }

    console.log("discountsActionsApi.data", discountsActionsApi.data);
  }, [discountsActionsApi.data]);

  useEffect(() => {}, [openQuantityDiscountFormModal]);

  //Filtering data
  useEffect(() => {
    setdata(quantityDiscounts);
  }, [quantityDiscounts]);

  const handleFilter = (e) => {
    const search_param = e;

    if (
      quantityDiscounts &&
      quantityDiscounts.length > 0 &&
      search_param &&
      search_param !== ""
    ) {
      setdata(
        quantityDiscounts.filter((x) =>
          x.title.toLowerCase().includes(search_param)
        )
      );
    } else {
      setdata(quantityDiscounts);
    }
  };

  return (
    <div>
      {openQuantityDiscountFormModal && (
        <PriceDiscountsFormModal
          ismodalOpen={openQuantityDiscountFormModal}
          setisModalOpen={setopenQuantityDiscountsFormModal}
          quantityDiscountToEdit={quantityDiscount}
          updated={updated}
          setUpdated={setUpdated}
          modalTitle={modalTitle}
        />
      )}
      <WholesaleQuantityDiscountsTable
        data={data}
        columns={columns}
        editAction={handleEditAction}
        detailsAction={handleDetailsAction}
        deleteAction={handleDeleteAction}
        addAction={handleAddAction}
        handleFilter={handleFilter}
      />
    </div>
  );
}

export default WholesaleQuantityDiscountsList;
